/**
 * ON_DEMAND trigger — an API-invokable trigger with typed input parameters.
 *
 * Maps to Java WorkflowOnDemandTriggerInput / OnDemandProperties.
 * Each input becomes a ServiceTaskParam that downstream tasks can
 * reference via ctx.trigger.<paramName>.
 */
import { FIELD_TYPE_MAP } from "../../entities/shared/types/field-types.js";
/**
 * Define an ON_DEMAND trigger with typed input parameters.
 *
 * @example
 * ```ts
 * onDemand({
 *   invoiceId: { type: "text", required: true },
 *   amount:    { type: "number", required: true },
 *   vendorName: { type: "text" },
 * })
 * ```
 */
export function onDemand(schema, options) {
    return {
        kind: "onDemand",
        schema,
        ...(options?.showTriggeredBy && { showTriggeredBy: true }),
        __triggerType: undefined,
    };
}
/**
 * Wrap a user-supplied `defaultValue` into the discriminated shape
 * mobius's POST endpoint requires.
 *
 * The mapping below pairs each EDK alias (what the user types) with
 * the matching field name on `WorkflowTriggerParameterDefaultValueInput`.
 * Two name asymmetries to watch out for and the reason this can't be
 * a 1-to-1 lookup keyed on the alias:
 *   - `boolean` (EDK) → `bool` (mobius field)
 *   - `user` (EDK)    → `userId` (mobius field)
 *
 * `json` and `object` are EDK-only aliases; mobius's record has no
 * default-value slot for them. We throw rather than emit a
 * silently-broken request — the user catches the misconfiguration
 * at deploy time with a message they can act on.
 *
 * Parameter is `FieldTypeAlias` (the full set), not
 * `TriggerFieldTypeAlias` (which excludes `"user"` for compile-time
 * safety on `TriggerInputFieldDef.type`). The runtime serializer
 * still has to route a `"user"` alias to `{ userId }` if one slips
 * through — see the test that asserts that mapping with `as never`.
 */
function wrapDefaultValueForWire(alias, value) {
    switch (alias) {
        case "text":
            return { text: value };
        case "number":
            // Mobius's record field is `Long` (`number` in the JSON), so a
            // fractional value would parse-fail downstream as
            // `Cannot deserialize java.lang.Long from "1.5"`. JS `number`
            // covers both ints and floats, so we have to runtime-check —
            // the TypeScript type alone can't enforce this. Refuse early
            // with a message that points the user at `decimal` rather than
            // letting mobius 400 mid-deploy with a generic Jackson error.
            if (typeof value !== "number" || !Number.isInteger(value)) {
                throw new TypeError(`onDemand input default value for type "number" must be an integer ` +
                    `(got ${JSON.stringify(value)}). Use type "decimal" for fractional ` +
                    `defaults — "number" is integer-only at the platform layer.`);
            }
            return { number: value };
        case "decimal":
            return { decimal: value };
        case "boolean":
            // Mobius's record field is named `bool`, not `boolean`.
            return { bool: value };
        case "date":
            // Expected wire form: "YYYY-MM-DD" — Jackson's LocalDate parser.
            return { date: value };
        case "datetime":
            // Expected wire form: ISO-8601 instant — Jackson's Instant parser.
            return { datetime: value };
        case "user":
            // Mobius's record field is named `userId`, not `user`.
            return { userId: value };
        case "attachmentId":
            return { attachmentId: value };
        case "record":
            throw new Error(`onDemand input default values are not supported for type "record". ` +
                `Build supplies the explicitly targeted app/element id as the parameter default.`);
        case "json":
        case "object":
            throw new Error(`onDemand input default values are not supported for type "${alias}". ` +
                `Defaults are only accepted for text / number / decimal / boolean / ` +
                `date / datetime / user. Drop the defaultValue, or pick a supported ` +
                `type for this input.`);
    }
}
export function serializeOnDemandTrigger(schema, options) {
    const inputs = Object.entries(schema).map(([name, def]) => {
        if (def.type === "record") {
            const runtimeDef = def;
            if (runtimeDef.multiple === true) {
                throw new Error(`On-demand record input "${name}" cannot be multiple`);
            }
            if (runtimeDef.defaultValue !== undefined) {
                throw new Error(`On-demand record input "${name}" cannot declare a defaultValue`);
            }
            return {
                name,
                type: FIELD_TYPE_MAP[def.type],
                required: def.required ?? false,
                multiple: false,
                app: def.app,
            };
        }
        return {
            name,
            type: FIELD_TYPE_MAP[def.type],
            required: def.required ?? false,
            multiple: def.multiple ?? false,
            // Skip when the user didn't set a default. The wire's omission
            // and `null` aren't the same — `null` would still try to
            // construct the wrapper record and fail.
            ...(def.defaultValue === undefined
                ? {}
                : { defaultValue: wrapDefaultValueForWire(def.type, def.defaultValue) }),
        };
    });
    return {
        onDemand: {
            inputs,
            ...(options?.showTriggeredBy && { showTriggeredBy: true }),
        },
    };
}
